const normalize = (value) => String(value || '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .trim().toLowerCase();

const dateParts = (date = new Date()) => {
  const items = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'America/Sao_Paulo',
    year: 'numeric', month: '2-digit', day: '2-digit'
  }).formatToParts(date);
  const value = Object.fromEntries(items.map(item => [item.type, item.value]));
  return { key: `${value.year}-${value.month}-${value.day}`, display: `${value.day}/${value.month}/${value.year}` };
};

const serialToDate = (serial) => {
  const base = new Date(Date.UTC(1899, 11, 30));
  base.setUTCDate(base.getUTCDate() + Math.floor(Number(serial)));
  return base;
};

const parseDate = (raw) => {
  if (raw === null || raw === undefined || raw === '') return null;

  if (raw instanceof Date && !isNaN(raw)) {
    return dateParts(raw);
  }

  if (typeof raw === 'number' || /^\d+(\.\d+)?$/.test(String(raw).trim())) {
    const asNumber = Number(raw);
    if (asNumber > 20000 && asNumber < 80000) {
      return dateParts(serialToDate(asNumber));
    }
  }

  const text = String(raw).trim();

  let match = text.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if (match) return { key: `${match[3]}-${match[2]}-${match[1]}`, display: text };

  match = text.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (match) return { key: `${match[1]}-${match[2]}-${match[3]}`, display: `${match[3]}/${match[2]}/${match[1]}` };

  return null;
};

const diffDays = (fromKey, toKey) => {
  const [fy, fm, fd] = fromKey.split('-').map(Number);
  const [ty, tm, td] = toKey.split('-').map(Number);
  const from = Date.UTC(fy, fm - 1, fd);
  const to = Date.UTC(ty, tm - 1, td);
  return Math.round((to - from) / 86400000);
};

const today = dateParts();
const reminders = [];

for (const item of $input.all()) {
  const row = item.json;

  const authorization = String(row['Codigo Autorização de Postagem'] || '').trim();
  const slackUserId = String(row['ID Slack do Solicitante'] || '').trim();

  if (!authorization || !slackUserId) continue;

  const expiration = parseDate(row['Vencimento da Autorização']);
  const status = normalize(row['Status Recebimento']);
  const lastReminder = parseDate(row['Última cobrança']);

  const overdue = !!expiration && expiration.key < today.key;
  const pendingReturn = status !== 'devolvido';
  const alreadyRemindedToday = lastReminder?.key === today.key;

  if (!overdue || !pendingReturn || alreadyRemindedToday) continue;

  const person = String(row['Nome do Atleta'] || 'colaborador').trim();
  const matricula = String(row['Matricula'] || '').trim();
  const currentStatus = String(row['Status Recebimento'] || 'sem status').trim();
  const modeloAtual = String(row['Modelo Atual'] || '').trim();
  const novoEquipamento = String(row['Novo Equipamento'] || '').trim();
  const equipamento = novoEquipamento || modeloAtual || 'não informado';
  const diasAtraso = diffDays(expiration.key, today.key);
  const diasLabel = diasAtraso === 1 ? '1 dia em atraso' : `${diasAtraso} dias em atraso`;

  reminders.push({
    json: {
      ...row,
      rowNumber: row.row_number,
      authorizationCode: authorization,
      slackUserId,
      cobrancaEm: today.key,
      slackBody: {
        channel: slackUserId,
        text: `🚨 Autorização ${authorization} de ${person} venceu em ${expiration.display} (${diasLabel}).`,
        blocks: [
          {
            type: 'header',
            text: { type: 'plain_text', text: '🚨 Autorização de postagem vencida', emoji: true }
          },
          {
            type: 'section',
            text: {
              type: 'mrkdwn',
              text: `⏰ *VENCIDA HÁ ${diasAtraso === 1 ? '1 DIA' : diasAtraso + ' DIAS'}* — venceu em *${expiration.display}*`
            }
          },
          { type: 'divider' },
          {
            type: 'section',
            fields: [
              { type: 'mrkdwn', text: `👤 *Colaborador*\n${person}` },
              { type: 'mrkdwn', text: `🪪 *Matrícula*\n${matricula || 'não informada'}` },
              { type: 'mrkdwn', text: `📋 *Autorização*\n${authorization}` },
              { type: 'mrkdwn', text: `📦 *Status de recebimento*\n${currentStatus}` },
              { type: 'mrkdwn', text: `💻 *Equipamento*\n${equipamento}` }
            ]
          },
          {
            type: 'section',
            text: {
              type: 'mrkdwn',
              text: '✅ Verifique a devolução e atualize o *Status Recebimento* na planilha para *Devolvido* assim que o equipamento retornar.\n📞 Se ele ainda não retornou, entre em contato com o colaborador responsável.'
            }
          },
          {
            type: 'actions',
            elements: [
              {
                type: 'button',
                text: { type: 'plain_text', text: '📄 Abrir planilha', emoji: true },
                url: 'https://docs.google.com/spreadsheets/d/SEU_SPREADSHEET_ID/edit#gid=0'
              }
            ]
          },
          {
            type: 'context',
            elements: [
              { type: 'mrkdwn', text: `🔔 Lembrete automático • ${today.display}` }
            ]
          }
        ]
      }
    }
  });
}

return reminders;
